rapla:artifact.body:
# rapla-view
# public: true
# updated: 2026-09-15T01:00

query LoanForm($reservationId: ID!) @view(title: "Loan form", listed: false)
  @param(name: "reservationId", into: "reservationId", required: true)
{
  reservation(id: $reservationId) {
    id
    name
    owner { username }
    appointments {
      status: compute(expr: "{p->name(attribute(p,\"loanStatus\"))}")
      period: compute(expr: "{p->format(\"%1$ta %1$td.%1$tm.%1$tY %1$tH:%1$tM\",start(p))} - {p->format(\"%1$ta %1$td.%1$tm.%1$tY %1$tH:%1$tM\",end(p))}")
      returnBy: compute(expr: "{p->format(\"%1$tA %1$td.%1$tm.%1$tY %1$tH:%1$tM\",end(p))}")
      borrowers: resources(filter: { isPersonEq: true }) {
        name
        classification {
          ... on borrowerClassification { firstname surname email phone department }
        }
      }
      items: resources(filter: { isPersonEq: false }) {
        name
        inventoryNumber: compute(expr: "inventoryNumber")
        condition: compute(expr: "condition")
        storageLocation: compute(expr: "storageLocation")
      }
    }
  }
}

# rapla-view
# public: true
# updated: 2026-09-15T00:00

query Loans(
  $filter: ReservationFilter!,
  $sort: [BlockSort!] = [{ field: END, dir: ASC }]
) @view(title: "Loans", rowLabel: "Loan|Loans", renderModes: [table, month])
  @window(from: {anchor: TODAY, offset: -30}, to: {anchor: TODAY, offset: 60})
{
  appointmentBlocks(filter: $filter, sort: $sort) {
    name  @column(header: "Loan", order: 1)
    start @column(header: "From", order: 2)
    end   @column(header: "Return", order: 3)
    status: compute(expr: "{p->if(and(equals(key(attribute(p,\"loanStatus\")),\"out\"),isBefore(end(p),now())),\"Overdue\",name(attribute(p,\"loanStatus\")))}")
      @column(header: "Status", order: 4)
    items: resources(filter: { isPersonEq: false })
      @join(separator: ", ") @column(header: "Items", order: 5) { id name }
    borrowers: resources(filter: { isPersonEq: true })
      @join(separator: ", ") @column(header: "Borrower", order: 6) { id name }
    color @hidden
    reservation @hidden { id canModify appointmentCount classification { typeKey } }
    appointment @hidden { id repeating { type } }
    matchedBy @hidden { id }
    isException @hidden
  }
}

{{! rapla-document
view: LoanForm
public: true
updated: 2026-09-15T00:00
}}
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>Loan form</title>
<style>
  body { font-family: Arial, Helvetica, sans-serif; font-size: 12px; line-height: 1.4;
         max-width: 17cm; margin: 1.5cm auto; color: #000; background: #fff; }
  h1 { font-size: 22px; margin: 0 0 .2em 0; }
  .org { color: #555; margin: 0 0 1.5em 0; }
  h2 { font-size: 14px; margin: 1.4em 0 .4em 0; }
  table { width: 100%; border-collapse: collapse; }
  th, td { border: 1px solid #999; padding: .3em .5em; text-align: left; vertical-align: top; }
  th { background: #eee; }
  dl { display: grid; grid-template-columns: 9em 1fr; gap: .2em 1em; margin: 0; }
  dt { font-weight: bold; }
  dd { margin: 0; }
  ol li { margin-bottom: .3em; }
  .sig { display: grid; grid-template-columns: 1fr 1fr; gap: 2em; margin-top: 3em; }
  .sig p { border-top: 1px solid #000; padding-top: .3em; margin: 0; }
  .return td { height: 2.5em; }
  @media print { @page { margin: 2cm; } body { margin: 0 auto; } }
</style>
</head>
<body>
{{> rapla/print-hint}}
{{#reservation}}
<h1>Loan form</h1>
<p class="org">Media Centre (example) · Service desk · Mon–Fri 09:00–16:00 · media-desk@example.org · +49 555 0100</p>
<dl>
  <dt>Loan</dt><dd>{{name}}</dd>

  <dt>Booked by</dt><dd>{{owner.username}}</dd>
</dl>
{{#appointments}}
<p><b>Status:</b> {{status}}</p>
<h2>Borrower</h2>
{{#borrowers}}
<dl>
  <dt>Name</dt><dd>{{name}}</dd>
  {{#classification}}
  {{#email}}<dt>Email</dt><dd>{{email}}</dd>{{/email}}
  {{#phone}}<dt>Phone</dt><dd>{{phone}}</dd>{{/phone}}
  {{#department}}<dt>Department</dt><dd>{{department}}</dd>{{/department}}
  {{/classification}}
</dl>
{{/borrowers}}
<h2>Loan period</h2>
<p>{{period}}</p>
<h2>Items</h2>
<table>
  <tr><th>Item</th><th>Inventory no.</th><th>Condition at hand-over</th><th>Storage location</th></tr>
  {{#items}}<tr><td>{{name}}</td><td>{{inventoryNumber}}</td><td>{{condition}}</td><td>{{storageLocation}}</td></tr>{{/items}}
</table>
<h2>Terms</h2>
<ol>
  <li>The items are lent for the purpose stated above and may not be passed on to third parties.</li>
  <li>The borrower checks the items at hand-over and reports visible defects immediately.</li>
  <li>Loss or damage during the loan period must be reported to the service desk without delay.</li>
  <li>The items are returned complete and on time, at the latest by {{returnBy}}.</li>
</ol>
{{/appointments}}
<div class="sig">
  <p>Date, signature service desk</p>
  <p>Date, signature borrower</p>
</div>
<h2>Return</h2>
<table class="return">
  <tr><th>Returned on</th><th>Complete / defects</th><th>Signature service desk</th></tr>
  <tr><td></td><td></td><td></td></tr>
</table>
{{/reservation}}
{{^reservation}}<p>Loan not found.</p>{{/reservation}}
</body>
</html>

{{! rapla-document
view: LoanForm
public: true
updated: 2026-09-15T00:00
}}
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>Return reminder</title>
<style>
  body { font-family: Arial, Helvetica, sans-serif; font-size: 13px; line-height: 1.5;
         max-width: 16cm; margin: 1.5cm auto; color: #000; background: #fff; }
  .mailhead { border: 1px solid #ccc; background: #f6f6f6; padding: .6em 1em; margin-bottom: 1.5em; }
  .mailhead p { margin: .1em 0; }
  .note { color: #666; font-size: 11px; margin-top: 2em; }
</style>
</head>
<body>
{{#reservation}}
{{#appointments}}
<div class="mailhead">
  <p><b>From:</b> media-desk@example.org</p>
  <p><b>To:</b> {{#borrowers}}{{#classification}}{{email}}{{/classification}} {{/borrowers}}</p>
  <p><b>Subject:</b> Reminder: please return "{{name}}"</p>
</div>
<p>Hello {{#borrowers}}{{#classification}}{{firstname}}{{/classification}}{{/borrowers}},</p>
<p>this is a friendly reminder that your loan <b>{{name}}</b> ends on <b>{{returnBy}}</b>.
Please bring the following items back to the service desk:</p>
<ul>
  {{#items}}<li>{{name}} ({{inventoryNumber}})</li>{{/items}}
</ul>
<p>If you need the items longer, reply to this mail before the return date.</p>
<p>Kind regards<br>Media Centre (example), service desk</p>
{{/appointments}}
<p class="note">Rendered as a document — Rapla does not send this mail.</p>
{{/reservation}}
{{^reservation}}<p>Loan not found.</p>{{/reservation}}
</body>
</html>
